import{_ as e,a as s}from"./chunks/沙箱环境.DpUk9W7n.js";import{_ as i}from"./chunks/发起转账.CTPkJlt5.js";import{_ as o,o as p,c as t,a2 as r}from"./chunks/framework.CqGPl1zp.js";const d="/newx-doc/assets/%E5%BA%94%E7%94%A8%E4%BF%A1%E6%81%AF.COdwckUa.png",l="/newx-doc/assets/%E8%B0%83%E7%94%A8PayTransferApi.B-q_ecq_.png",n="/newx-doc/assets/%E5%AE%9E%E7%8E%B0%E5%9B%9E%E8%B0%83%E6%8E%A5%E5%8F%A3.D8bGlxG6.png",c="/newx-doc/assets/%E5%88%9B%E5%BB%BA%E7%A4%BA%E4%BE%8B%E6%8F%90%E7%8E%B0%E5%8D%95.BT6L6XyG.png",h="/newx-doc/assets/%E6%B5%8B%E8%AF%95-%E8%BD%AC%E8%B4%A6%E5%9B%9E%E8%B0%83.B3dtobUV.png",B=JSON.parse('{"title":"支付宝转账接入","description":"","frontmatter":{},"headers":[],"relativePath":"pay/alipay-transfer-demo.md","filePath":"pay/alipay-transfer-demo.md","lastUpdated":null}'),m={name:"pay/alipay-transfer-demo.md"};function E(k,a,y,u,g,_){return p(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="支付宝转账接入" tabindex="-1">支付宝转账接入 <a class="header-anchor" href="#支付宝转账接入" aria-label="Permalink to &quot;支付宝转账接入&quot;">​</a></h1><h2 id="_0-概述" tabindex="-1">0. 概述 <a class="header-anchor" href="#_0-概述" aria-label="Permalink to &quot;0. 概述&quot;">​</a></h2><p>在 <code>yudao-module-pay</code> 模块的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/tree/master/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/controller/admin/demo" target="_blank" rel="noreferrer"><code>demo</code></a> 模块，我们提供了一个 <strong>转账</strong> 接入的示例（PayDemoWithdrawController）。</p><p>它支持如下支付（转账）渠道：</p><ul><li>支付宝转账</li><li>钱包转账</li></ul><p>疑问：为什么不支持微信转账呢？</p><p>因为 <code>demo</code> 是使用 PC 网页提供示例，而微信转账流程依赖微信公众号、小程序等，所以不太好支持！</p><p>如果你有这方面的诉求，可以阅读 <a href="./wx-transfer-demo">《微信转账接入》</a></p><p>下面，我们以 <code>demo</code> 模块为例子，讲解如何接入支付宝的转账功能。</p><h2 id="_1-第一步-配置支付渠道" tabindex="-1">1. 第一步，配置支付渠道 <a class="header-anchor" href="#_1-第一步-配置支付渠道" aria-label="Permalink to &quot;1. 第一步，配置支付渠道&quot;">​</a></h2><p>① 在 [支付管理 -&gt; 应用信息] 菜单，新建 <code>demo</code> 模块使用的支付应用。如下图所示：</p><p><img src="'+d+'" alt="应用信息"></p><ul><li>转账结果的回调地址：对应「2.4 第四步，实现回调接口」实现的接口。这里因为我们在本地演示，所以使用了 <code>127.0.0.1</code> IP 地址，如果你部署到服务器上，要设置服务器可调用到的 IP 地址。</li></ul><p>因为 <code>demo</code> 模块的支付应用默认已经创建，所以你可以直接使用。注意，这里的应用标识 <strong>“demo”</strong> 稍后会使用到。</p><p>疑问：为什么应用上有回调地址，然后 <code>application.yaml</code> 配置文件中也有 <code>yudao.pay.transfer-notify-url</code> 回调地址呢？</p><p>请详细阅读 <a href="./build">《支付手册 —— 功能开启》</a> 的「3.5 支付回调【重要】」小节。</p><p>简单来说：</p><ul><li>配置文件的回调地址，是外部的支付渠道（支付宝、微信）回调 <code>pay</code> 支付模块（支付中心）的地址。</li><li>应用的回调地址，是 <code>pay</code> 回调内部的各个 <code>biz</code> 模块（支付应用）的地址。例如收：<code>trade</code> 商城的分销提现的转账</li></ul><p>因为内部会有多个业务模块，所以它们每个都有自己的回调地址，就是配置到对应的支付应用上！</p><p>② 点击“示例用户”对应的【支付宝 PC 网站支付】，进入支付渠道的配置。如下图所示：</p><p><img src="'+e+'" alt="支付渠道"></p><p>友情提示：</p><p>如果你还没有支付宝开放平台的账号，可以先参考 <a href="https://opendocs.alipay.com/common/02kkv7" target="_blank" rel="noreferrer">《沙箱环境》</a> 文档，申请一个测试账号，我目前就是这么测试的。只需要阅读该文档的如下小节即可：</p><p><img src="'+s+`" alt="沙箱环境"></p><p>最终在 <a href="https://open.alipay.com/develop/sandbox/app" target="_blank" rel="noreferrer">沙箱应用</a> 可以看到支付渠道的配置。</p><h2 id="_2-第二步-实现转账调用【重要】" tabindex="-1">2. 第二步，实现转账调用【重要】 <a class="header-anchor" href="#_2-第二步-实现转账调用【重要】" aria-label="Permalink to &quot;2. 第二步，实现转账调用【重要】&quot;">​</a></h2><p>友情提示：由于 demo 模块的转账接入已经实现，这里你只要看懂什么意思即可，不用操作。</p><p>① 【后端】在 <code>demo</code> 模块所在的 <code>yudao-module-xx</code> 模块的 <code>pom.xml</code> 文件，引入 <code>yudao-module-pay</code> 依赖，这样才可以调用到 PayTransferApi 接口。代码如下：</p><div class="language-XML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">XML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;cn.iocoder.boot&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;yudao-module-pay&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;\${revision}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependency</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>② 【后端】在 <code>demo</code> 模块的转账逻辑中，需要调用 PayTransferApi 的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master-jdk17/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/service/demo/PayDemoWithdrawServiceImpl.java#L77-L87" target="_blank" rel="noreferrer"><code>#createTransfer(...)</code></a> 方法，创建转账单。如下图所示：</p><p>图片纠错：最新版本不区分 yudao-module-pay-api 和 yudao-module-pay-biz 子模块，代码直接合并到 yudao-module-pay 模块的 src 目录下，更适合单体项目</p><p><img src="`+l+'" alt="调用 PayOrderApi"></p><h2 id="_3-第三部-实现回调接口【重要】" tabindex="-1">3. 第三部，实现回调接口【重要】 <a class="header-anchor" href="#_3-第三部-实现回调接口【重要】" aria-label="Permalink to &quot;3. 第三部，实现回调接口【重要】&quot;">​</a></h2><p>友情提示：由于 demo 模块的转账接入已经实现，这里你只要看懂什么意思即可，不用操作。</p><p>在 <code>demo</code> 模块所在的 <code>yudao-module-xx</code> 模块，实现一个转账回调的接口，提供给支付【中心】回调。对应的代码在 PayDemoWithdrawController 的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master-jdk17/yudao-module-pay/src/main/java/cn/iocoder/yudao/module/pay/controller/admin/demo/PayDemoWithdrawController.java#L54-L61" target="_blank" rel="noreferrer"><code>#updateDemoWithdrawTransferred(...)</code></a> 方法中，如下图所示：</p><p><img src="'+n+'" alt="实现回调接口"></p><h2 id="_4-第四步-转账功能测试" tabindex="-1">4. 第四步，转账功能测试 <a class="header-anchor" href="#_4-第四步-转账功能测试" aria-label="Permalink to &quot;4. 第四步，转账功能测试&quot;">​</a></h2><p>至此，我们已经完成了转账接入的所有步骤，接下来，我们来测试一下转账功能。</p><p>① 打开 [支付管理 -&gt; 接入示例 -&gt; 提现转账案例] 菜单，点击【创建示例提现单】按钮，创建一个提现单。如下图所示：</p><p><img src="'+c+'" alt="创建示例提现单"></p><p>此时，只是创建了一个提现单，并没有调用 PayTransferApi 发起转账。</p><p>② 创建完成后，点击该提现单的【发起转账】按钮，发起转账流程。如下图所示：</p><p><img src="'+i+'" alt="发起转账"></p><p>此时，才会调用 PayTransferApi 发起转账，而在 <code>pay_transfer</code> 表中，会新增一条转账记录。</p><p>然后，它的转账状态会变为【转账中】。刷新几次列表，可以看到转账状态变为【转账成功】或者【转账失败】。</p><p>③ 转账完成后，先是支付【中心】的回调接口被回调，然后是 <code>demo</code> 模块的回调接口被回调。如下图所示：</p><p><img src="'+h+'" alt="转账回调"></p><p>至此，我们已经完成转账接入的测试流程，可以试着多多 debug 调试整个流程，并不复杂噢。</p>',48)])])}const P=o(m,[["render",E]]);export{B as __pageData,P as default};
